# ---------------------------------------------------------------------------
# Append-only guard for opportunity_history (defence in depth; the ORM also refuses).
# ---------------------------------------------------------------------------

APPEND_ONLY_MESSAGE = "opportunity_history is append-only"


def _create_append_only_triggers() -> None:
    dialect = op.get_bind().dialect.name
    if dialect == "sqlite":
        for action in ("UPDATE", "DELETE"):
            op.execute(
                f"CREATE TRIGGER opportunity_history_no_{action.lower()} BEFORE {action} ON opportunity_history "
                f"BEGIN SELECT RAISE(ABORT, '{APPEND_ONLY_MESSAGE}'); END;"
            )
    elif dialect == "postgresql":
        op.execute(
            "CREATE FUNCTION opportunity_history_append_only() RETURNS trigger AS $$ "
            f"BEGIN RAISE EXCEPTION '{APPEND_ONLY_MESSAGE}'; END; $$ LANGUAGE plpgsql;"
        )
        for action in ("UPDATE", "DELETE"):
            op.execute(
                f"CREATE TRIGGER opportunity_history_no_{action.lower()} BEFORE {action} ON opportunity_history "
                "FOR EACH ROW EXECUTE FUNCTION opportunity_history_append_only();"
            )
    else:
        raise NotImplementedError(f"No append-only trigger defined for {dialect}")


def _drop_append_only_triggers() -> None:
    dialect = op.get_bind().dialect.name
    if dialect == "sqlite":
        op.execute("DROP TRIGGER IF EXISTS opportunity_history_no_update")
        op.execute("DROP TRIGGER IF EXISTS opportunity_history_no_delete")
    elif dialect == "postgresql":
        op.execute("DROP TRIGGER IF EXISTS opportunity_history_no_update ON opportunity_history")
        op.execute("DROP TRIGGER IF EXISTS opportunity_history_no_delete ON opportunity_history")
        op.execute("DROP FUNCTION IF EXISTS opportunity_history_append_only()")
